(function(E){ const x = E["sales-m4"] = E["sales-m4"] || {units:{}}; x.units["sales-4-2"] = {"grammar":{"id":"c-sales-4-2-g","level":"B1","course":"sales","unit":"sales-4-2","title":"News and updates: We have found... / They told us yesterday...","titleTr":"Haberler ve güncellemeler: We have found... / They told us yesterday...","titleFa":"خبر و به‌روزرسانی: We have found... و They told us yesterday...","formsTable":{"headers":{"en":["Use","Form","Example"],"tr":["Kullanım","Biçim","Örnek"],"fa":["کاربرد","ساختار","مثال"]},"rows":[["news now, no time","have / has + past participle","We have found a problem with the second shipment."],["not yet","hasn't / haven't + past participle + yet","The permit hasn't arrived yet."],["finished time","past simple","The port told us on Friday."]]},"wrong":"The port has told us on Friday that it needs ten more days.","right":"The port told us on Friday that it needs ten more days.","blank":{"sentence":"I'm afraid the import permit ___ yet.","word":"hasn't arrived","distractors":["isn't arrived","hasn't arrive"]},"wrong2":"Last week we have booked space on the next ship.","right2":"Last week we booked space on the next ship.","blank2":{"sentence":"The shipping line ___ us on Friday that the ship is late.","word":"told","distractors":["has told","has been telling"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"News that matters now, with no time given, takes have / has + past participle.","tr":"Şu an önemli olan ve zamanı verilmeyen haber have / has + fiilin üçüncü hâlini alır.","fa":"برای خبری که الان مهم است و زمانش را نمی‌گویی، have یا has و اسم مفعول می‌آوری.","ex":"We have found a problem with the second shipment."},{"en":"A finished time word needs the past simple.","tr":"Bitmiş bir zaman ifadesi past simple ister.","fa":"قید زمان تمام‌شده، مثل yesterday، گذشته‌ی ساده می‌خواهد.","ex":"The port told us on Friday."},{"en":"Yet and already look at now, so they take the present perfect.","tr":"yet ve already şimdiye bakar; bu yüzden present perfect ile kullanılır.","fa":"کلمه‌های yet و already به اکنون نگاه می‌کنند، پس با حال کامل می‌آیند.","ex":"The permit hasn't arrived yet."}],"test":{"en":"Look for yesterday, on Friday, last week. Found one? Use the past simple, not have.","tr":"yesterday, on Friday, last week gibi ifadelere bak. Varsa have değil, past simple kullan.","fa":"دنبال yesterday، on Friday یا last week بگرد. اگر پیدا کردی، گذشته‌ی ساده بیاور، نه have."},"contrast":{"en":"Turkish uses '-dı' for both ('Bir sorun bulduk', 'Cuma günü söylediler'), and Persian can say «جمعه به ما گفته‌اند» with a perfect form. English is strict: a finished time means past simple.","tr":"Türkçede ikisi için de '-dı' kullanırız: 'Bir sorun bulduk', 'Cuma günü söylediler'. İngilizce bu konuda katıdır: haber şu an önemliyse ve zaman yoksa have found; bitmiş bir zaman varsa told.","fa":"در فارسی می‌شود گفت «جمعه به ما گفته‌اند»، یعنی ماضی نقلی همراه با زمان. انگلیسی سخت‌گیرتر است: اگر زمان تمام‌شده‌ای را بگویی، فقط گذشته‌ی ساده درست است."}},"errorWatch":[{"find":["has told us yesterday","has told us on","have booked last","have found yesterday","have sent yesterday","has arrived yesterday","have received yesterday","have shipped last"],"fix":{"en":"With a finished time (yesterday, last week, on Friday), use the past simple: 'They told us on Friday.'","tr":"Bitmiş bir zamanla (yesterday, last week, on Friday) past simple kullan: 'They told us on Friday.'","fa":"با زمان تمام‌شده (yesterday، last week، on Friday) گذشته‌ی ساده بیاور: «They told us on Friday.»"}},{"find":["isn't arrived","hasn't arrive","haven't receive","hasn't finish","haven't finish"],"fix":{"en":"Present perfect: has / have + past participle: 'hasn't arrived'.","tr":"Present perfect: has / have + fiilin üçüncü hâli: 'hasn't arrived'.","fa":"برای حال کامل has یا have و اسم مفعول بیاور: hasn't arrived."}}]},"b2":{"id":"c-sales-4-2-b2","level":"B2","track":"B2","course":"sales","unit":"sales-4-2","title":"Showing effort: We have been calling them since Monday","titleTr":"Çabayı göstermek: We have been calling them since Monday","titleFa":"نشان دادن تلاش: We have been calling them since Monday","formsTable":{"headers":{"en":["Form","Example"],"tr":["Biçim","Örnek"],"fa":["ساختار","مثال"]},"rows":[["have / has been + -ing + since","We have been calling them since Monday."],["have / has been + -ing + for","We have been waiting for two weeks."],["not: am / are + -ing + since","not: We are calling them since Monday."]]},"wrong":"We are calling the port every day since Monday.","right":"We have been calling the port every day since Monday.","blank":{"sentence":"Our team ___ on this since Monday morning.","word":"has been working","distractors":["is working","works"]},"wrong2":"We have been wait for the permit for two weeks.","right2":"We have been waiting for the permit for two weeks.","blank2":{"sentence":"Our agent has been ___ the shipping line every day.","word":"calling","distractors":["call","called"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Started in the past, still going on: have / has been + -ing.","tr":"Geçmişte başladı, hâlâ sürüyor: have / has been + -ing.","fa":"برای کاری که در گذشته شروع شده و ادامه دارد، have been یا has been و فعل با ing می‌آوری.","ex":"We have been calling them since Monday."},{"en":"since + a start point; for + a length of time.","tr":"since + başlangıç noktası; for + süre.","fa":"بعد از since نقطه‌ی شروع می‌آید و بعد از for مدت زمان.","ex":"since Monday / for two weeks"},{"en":"Not am / is / are + -ing with since or for.","tr":"since ya da for ile am / is / are + -ing olmaz.","fa":"با since یا for از am، is یا are و فعل با ing استفاده نکن.","ex":"not: We are calling them since Monday"}],"test":{"en":"See since or for? Check that have been comes before the -ing.","tr":"since ya da for görüyor musun? -ing'den önce have been olduğunu kontrol et.","fa":"since یا for می‌بینی؟ مطمئن شو پیش از ‎-ing، have been آمده باشد."},"contrast":{"en":"Turkish says 'Pazartesiden beri arıyoruz' and Persian «از دوشنبه داریم زنگ می‌زنیم», both present tense. That is why learners write 'we are calling since Monday'. English needs have been + -ing.","tr":"Türkçede 'Pazartesiden beri arıyoruz' deriz; şimdiki zamanla. Bu yüzden İngilizcede 'we are calling since Monday' yazılıyor. İngilizcede have been + -ing gerekir.","fa":"در فارسی می‌گوییم «از دوشنبه داریم زنگ می‌زنیم»، با زمان حال. برای همین خیلی از ما می‌نویسیم we are calling since Monday. انگلیسی have been + ‎-ing لازم دارد."}},"errorWatch":[{"find":["are calling them since","are waiting since","are working since","is waiting since","is working on it since","have been wait","have been call","has been work"],"fix":{"en":"With since or for: have / has been + -ing: 'We have been calling them since Monday.'","tr":"since ya da for ile: have / has been + -ing: 'We have been calling them since Monday.'","fa":"با since یا for باید have been یا has been و فعل با ing بیاوری: «We have been calling them since Monday.»"}}],"useIn":{"en":"B2: show your effort once with have been + -ing and since or for.","tr":"B2: çabanı bir kez have been + -ing ve since ya da for ile göster.","fa":"مسیر B2: یک بار تلاشت را با have been و فعل با ing، همراه با since یا for، نشان بده."},"exitItem":{"from":"sales-4-2","kind":"blank","prompt":"We ___ for the new permit since 12 May.","options":["are waiting","wait","have been waiting"],"correct":2,"why":{"en":"have been waiting: 'since' with an action that is still going on. 'Are waiting' and 'wait' can't go with since.","tr":"have been waiting: 'since' ve hâlâ süren bir eylem. 'Are waiting' ve 'wait' since ile kullanılmaz.","fa":"have been waiting درست است، چون since با کاری می‌آید که هنوز ادامه دارد. are waiting و wait با since نمی‌آیند."}}},"vocab":{"id":"c-sales-4-2-v","level":"B1","category":"vocab","course":"sales","unit":"sales-4-2","goals":["career"],"title":{"en":"Delays and updates","tr":"Gecikmeler ve bilgilendirme","fa":"تأخیر و خبررسانی"},"cards":[{"word":"delay","sentence":"The delay is two weeks.","meaning":{"en":"Time when something is later than planned.","tr":"gecikme.","fa":"تأخیر"}},{"word":"on schedule","sentence":"The first shipment is on schedule.","meaning":{"en":"Happening at the planned time.","tr":"planlanan zamanda.","fa":"طبق برنامه"}},{"word":"behind schedule","sentence":"We are a week behind schedule.","meaning":{"en":"Later than planned.","tr":"planın gerisinde.","fa":"عقب‌تر از برنامه"}},{"word":"customs clearance","sentence":"Customs clearance took three more days.","meaning":{"en":"Official permission for goods to enter or leave a country.","tr":"gümrükleme","fa":"ترخیص کالا از گمرک"}},{"word":"part-shipment","sentence":"We can offer a part-shipment next week.","meaning":{"en":"Sending some of the order now and the rest later.","tr":"kısmi sevkiyat","fa":"ارسال بخشی از سفارش"}},{"word":"update","sentence":"I'll send you an update on Friday.","meaning":{"en":"New information about a situation.","tr":"güncel bilgi.","fa":"گزارش تازه؛ به‌روزرسانی"}},{"word":"unfortunately","sentence":"Unfortunately, the ship is late.","meaning":{"en":"Used before bad news.","tr":"maalesef.","fa":"متأسفانه"}},{"word":"estimated","sentence":"The estimated arrival date is 8 June.","meaning":{"en":"Guessed as well as possible, not exact.","tr":"tahmini.","fa":"تخمینی"}},{"word":"alternative","sentence":"The alternative is air freight.","meaning":{"en":"Another possible choice.","tr":"alternatif, seçenek.","fa":"گزینه‌ی دیگر"}},{"word":"informed","sentence":"We'll keep you informed.","meaning":{"en":"Knowing the latest news.","tr":"bilgilendirilmiş, haberdar.","fa":"در جریان؛ باخبر"}}]},"judge":{"id":"c-sales-4-2-j","course":"sales","unit":"sales-4-2","type":"judge","title":{"en":"Is it good bad news?","tr":"İyi bir kötü haber mi?","fa":"این خبر بد را خوب داده است؟"},"prompt":"Four messages about a late shipment of 20 pallets.","parts":["News first","Reason","New date and action"],"instruction":{"en":"Tap what each message has. The one to send has all three.","tr":"Her mesajda ne olduğuna dokun. Gönderilecek olanda üçü de var.","fa":"روی چیزهایی که هر پیام دارد بزن. پیامی که باید بفرستی هر سه را دارد."},"items":[{"by":"AI tool","answer":"We hope this message finds you well. As you know, global logistics can be challenging at times, and we are committed to excellence.","present":[],"fix":{"en":"Where is the news? Start with the old date and the new date.","tr":"Haber nerede? Eski ve yeni tarihle başla.","fa":"خبر کجاست؟ با تاریخ قبلی و تاریخ جدید شروع کن."}},{"by":"New rep","answer":"Your goods will be late. Sorry.","present":["News first"],"fix":{"en":"Honest, but it leaves the buyer with no plan. How late, why, and what are you doing?","tr":"Dürüst ama alıcıyı plansız bırakıyor. Ne kadar geç, neden ve ne yapıyorsun?","fa":"صادقانه است، ولی خریدار را بی‌برنامه می‌گذارد. چقدر دیر می‌شود، چرا و چه می‌کنی؟"}},{"by":"Sales rep","answer":"The shipping line changed its schedule on Monday, and the port is very busy. We have spoken to our agent. Your 20 pallets will now arrive on 8 June.","present":["Reason","New date and action"],"fix":{"en":"All the facts, but the news is at the end. Put the new date first.","tr":"Bütün bilgiler var ama haber sonda. Yeni tarihi başa koy.","fa":"همه‌ی واقعیت‌ها هست، ولی خبر آخر از همه آمده. تاریخ جدید را اول بگذار."}},{"by":"Good model","answer":"Your 20 pallets will arrive on 8 June, not 1 June. The shipping line changed its schedule on Monday. We have booked the next ship, and I'll update you on Friday.","present":["News first","Reason","New date and action"],"fix":null}]},"speaking":{"id":"sales-4-2","course":"sales","unit":"sales-4-2","topic":{"en":"The bad news call","tr":"Kötü haber araması","fa":"تماس خبر بد"},"warmup":{"en":"When did a supplier last give you bad news? How did it feel?","tr":"Bir tedarikçi sana en son ne zaman kötü haber verdi? Nasıl hissettirdi?","fa":"آخرین بار کی یک تأمین‌کننده به تو خبر بد داد؟ چه حسی داشت؟"},"questions":[{"en":"Call a buyer. The container will be 10 days late. Say the news in your first sentence.","tr":"Bir alıcıyı ara. Konteyner 10 gün gecikecek. Haberi ilk cümlende söyle.","fa":"به یک خریدار زنگ بزن. کانتینر ۱۰ روز دیر می‌رسد. خبر را در جمله‌ی اولت بگو."},{"en":"The buyer asks: 'Why are we only hearing this now?' Answer honestly, with past simple and present perfect.","tr":"Alıcı soruyor: 'Why are we only hearing this now?' Geçmiş zaman ve present perfect ile dürüstçe cevap ver.","fa":"خریدار می‌پرسد: «Why are we only hearing this now?» با گذشته‌ی ساده و حال کامل صادقانه جواب بده."},{"en":"Give a new date, one real choice for the buyer, and when you will call again.","tr":"Yeni bir tarih, alıcı için gerçek bir seçenek ve ne zaman yeniden arayacağını söyle.","fa":"تاریخ جدید، یک حق انتخاب واقعی برای خریدار و زمان تماس بعدی‌ات را بگو."}],"followups":[{"en":"What bad news is most likely in your own work? Say your first sentence.","tr":"Kendi işinde en olası kötü haber ne? İlk cümleni söyle.","fa":"در کار خودت کدام خبر بد محتمل‌تر است؟ جمله‌ی اولت را بگو."}],"expressions":[{"phrase":"I'm calling with some bad news.","meaning":{"en":"Says it at once.","tr":"Hemen söyler.","fa":"خبر را فوری می‌گوید."}},{"phrase":"We have just found out that ...","meaning":{"en":"Gives fresh news.","tr":"Yeni haberi verir.","fa":"خبر تازه را می‌دهد."}},{"phrase":"I'll update you on ...","meaning":{"en":"Sets your next message.","tr":"Bir sonraki mesajını belirler.","fa":"زمان پیام بعدی‌ات را مشخص می‌کند."}}],"model":"I'm calling with some bad news. Your container will be ten days late. We have just found out that the ship is delayed at the port. The shipping line told us this morning, and I'm calling you first. You can wait for the eighteenth, or we can send five pallets by air next week. Which is better for you? I'll update you on Friday.","selfCheck":[{"en":"The news was in my first sentence.","tr":"Haber ilk cümlemdeydi.","fa":"خبر در جمله‌ی اولم بود."},{"en":"I gave one reason, without blame.","tr":"Suçlamadan tek bir neden verdim.","fa":"یک دلیل دادم، بدون مقصر دانستن کسی."},{"en":"I gave a new date and a choice.","tr":"Yeni bir tarih ve bir seçenek sundum.","fa":"تاریخ جدید و یک حق انتخاب دادم."},{"en":"I used past simple with finished times.","tr":"Bitmiş zamanlarla geçmiş zaman kullandım.","fa":"با زمان‌های تمام‌شده گذشته‌ی ساده به کار بردم."}]},"writing":{"id":"c-sales-4-2-w","course":"sales","unit":"sales-4-2","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your delay message","tr":"Gecikme mesajın","fa":"پیام تأخیر تو"},"portfolio":null,"prompt":{"en":"Use a real delay, or: 20 pallets of tiles due 1 June; your second order is on schedule; the shipping line changed its schedule on Monday; next ship arrives 8 June; 5 pallets could go by air at extra cost. Write the email (70-100 words): the news first, what is still on schedule, the reason, the new date, a choice, and your next update.","tr":"Gerçek bir gecikme ya da şunu kullan: 1 Haziran'da gelecek 20 palet fayans; ikinci siparişin takviminde; denizcilik şirketi pazartesi günü takvimini değiştirdi; sonraki gemi 8 Haziran'da varıyor; 5 palet ek ücretle havayoluyla gidebilir. E-postayı yaz (70-100 kelime): önce haber, hâlâ takvimde olan şey, neden, yeni tarih, bir seçenek ve bir sonraki bilgilendirme.","fa":"از یک تأخیر واقعی یا این استفاده کن: ۲۰ پالت کاشی برای ۱ ژوئن؛ سفارش دوم طبق برنامه است؛ خط کشتیرانی دوشنبه برنامه‌اش را عوض کرده؛ کشتی بعدی ۸ ژوئن می‌رسد؛ ۵ پالت می‌تواند با هزینه‌ی اضافه هوایی برود. ایمیل را بنویس (۷۰ تا ۱۰۰ کلمه): اول خبر، چیزی که هنوز طبق برنامه است، دلیل، تاریخ جدید، یک انتخاب و زمان خبر بعدی."},"model":"Dear Mr Tanaka,\n\nYour 20 pallets of tiles will arrive on 8 June, not 1 June. The second order is still on schedule. The shipping line changed its schedule on Monday, and we have booked the next ship. If you need some tiles sooner, we can send five pallets by air at extra cost. Which would you prefer? I'm sorry for the change. I will update you on Friday.\n\nBest regards","frame":"Dear ___,\n\nYour ___ will arrive on ___, not ___. ___ is still on schedule. ___ on ___, and we have ___. If you need ___, we can ___. Which would you prefer? I'm sorry for ___. I will update you on ___.\n\nBest regards","words":[{"word":"not 1 June"},{"word":"on schedule"},{"word":"we have booked"}],"minWords":60,"minSentences":5,"rubric":["Task done: news, what is on schedule, reason, new date, choice, next update","Organised: the news in the first line","Language: present perfect for news; past simple with a finished time","Tone: honest and calm, no fog and no blame"],"rubricI18n":{"tr":["Görev: haber, takvimde olan, neden, yeni tarih, seçenek, sonraki bilgilendirme","Düzen: haber ilk satırda","Dil: haber için present perfect; bitmiş zamanla geçmiş zaman","Üslup: dürüst ve sakin; sisli söz ve suçlama yok"],"fa":["کامل بودن کار: خبر، چیزی که طبق برنامه است، دلیل، تاریخ جدید، انتخاب، خبر بعدی","نظم: خبر در خط اول","زبان: حال کامل برای خبر؛ گذشته‌ی ساده با زمان تمام‌شده","لحن: صادق و آرام؛ بدون ابهام و مقصر دانستن کسی"]}},"exit":{"id":"c-sales-4-2-x","course":"sales","unit":"sales-4-2","type":"exit","items":[{"from":"sales-4-2","kind":"blank","prompt":"The shipping line ___ us yesterday that the ship is full.","options":["has told","told","has been telling"],"correct":1,"point":2,"why":{"en":"told: 'yesterday' is a finished time, so use the past simple. 'Has told' and 'has been telling' cannot go with yesterday.","tr":"told: 'yesterday' bitmiş bir zamandır, bu yüzden past simple. 'Has told' ve 'has been telling' yesterday ile kullanılmaz.","fa":"told درست است، چون yesterday زمان تمام‌شده است و گذشته‌ی ساده می‌خواهد. has told و has been telling با yesterday نمی‌آیند."}},{"from":"sales-4-2","kind":"mcq","prompt":"Where does the news go in a bad news email?","options":["In the first line","After the company history","At the end, if there is room"],"correct":0,"point":1,"why":{"en":"In the first line: the reader needs the news to act. Putting it after your history or at the end looks like hiding it.","tr":"İlk satırda: okurun harekete geçmek için habere ihtiyacı var. Onu tarihçenin arkasına ya da sona koymak saklıyormuşsun gibi görünür.","fa":"در خط اول، چون خواننده برای تصمیم گرفتن به خبر نیاز دارد. گذاشتنش بعد از تاریخچه یا در آخر این حس را می‌دهد که داری پنهانش می‌کنی."}},{"from":"sales-4-2","kind":"mcq","prompt":"Which new date should you give?","options":["The earliest date you can hope for","A date you are sure you can keep","No date at all"],"correct":1,"point":1,"why":{"en":"A date you are sure you can keep: a second delay hurts trust more than the first. The earliest hope may slip, and no date leaves them stuck.","tr":"Tutabileceğinden emin olduğun bir tarih: ikinci gecikme güveni ilkinden daha çok zedeler. En erken umut kayabilir; tarih vermemek de onları belirsizlikte bırakır.","fa":"تاریخی که مطمئنی می‌توانی سرش بمانی؛ تأخیر دوم بیشتر از اولی به اعتماد ضربه می‌زند. زودترین تاریخ امیدوارانه ممکن است عقب بیفتد و بی‌تاریخ هم آن‌ها را بلاتکلیف می‌گذارد."}},{"from":"sales-4-1","kind":"blank","prompt":"The buyer ___ us that half the boxes were open.","options":["told","said","spoke"],"correct":0,"point":2,"why":{"en":"told: 'tell' takes a person: told us that. 'Said' takes no person after it, and 'spoke' doesn't report words this way.","tr":"told: 'tell' kişi alır: told us that. 'Said' kendinden sonra kişi almaz; 'spoke' sözleri bu şekilde aktarmaz.","fa":"told درست است، چون tell شخص می‌خواهد: told us that. بعد از said شخص نمی‌آید و spoke حرف را این‌طوری نقل نمی‌کند."}},{"from":"sales-3-3","kind":"mcq","prompt":"If the PO and the quote don't match, you should ___","options":["ship anyway.","raise it in writing now.","wait for the buyer to notice."],"correct":1,"point":1,"why":{"en":"Raise it in writing now: a mismatch found later can stop payment or the goods. Shipping anyway or waiting makes it worse.","tr":"Şimdi yazılı olarak bildir: sonradan fark edilen bir uyumsuzluk ödemeyi ya da malı durdurabilir. Yine de göndermek ya da beklemek durumu kötüleştirir.","fa":"همین الان کتبی مطرحش کن؛ ناهماهنگی که دیر پیدا شود می‌تواند پول یا کالا را متوقف کند. فرستادن بی‌توجه یا صبر کردن اوضاع را بدتر می‌کند."}},{"from":"sales-2-1","kind":"blank","prompt":"Who ___ your packaging these days?","options":["supply","is supply","supplies"],"correct":2,"point":2,"why":{"en":"supplies: 'who' is the subject, so add -s and no 'do'. 'Supply' is plural, and 'is supply' mixes two verbs.","tr":"supplies: 'who' öznedir; -s eklenir, 'do' gelmez. 'Supply' çoğuldur; 'is supply' iki fiili karıştırır.","fa":"supplies درست است، چون who فاعل است؛ پس ‎-s می‌گیرد و do نمی‌خواهد. supply جمع است و is supply دو فعل را قاطی می‌کند."}}]},"explain":{"id":"c-sales-4-2-e","course":"sales","unit":"sales-4-2","type":"explain","level":"B1","title":{"en":"Giving bad news early","tr":"Kötü haberi erken vermek","fa":"زود دادن خبر بد"},"objective":{"en":"After this lesson, you can give a customer bad news early, with the reason, a new date and what you are doing about it.","tr":"Bu dersin sonunda müşteriye kötü haberi erken, nedeni, yeni tarihi ve bu konuda ne yaptığınla birlikte verebileceksin.","fa":"بعد از این درس می‌توانی خبر بد را زود به مشتری بدهی، همراه با دلیل، تاریخ جدید و کاری که برایش می‌کنی."},"hook":{"en":"Tell the customer bad news as soon as you know, with the reason and a new date. Customers can plan around bad news, but they can't plan around silence.","tr":"Kötü haberi öğrenir öğrenmez, nedeni ve yeni tarihiyle müşteriye söyle. Müşteriler kötü habere göre plan yapabilir, sessizliğe göre yapamaz.","fa":"خبر بد را همین که فهمیدی به مشتری بگو، همراه با دلیل و تاریخ جدید. مشتری می‌تواند با خبر بد برنامه‌ریزی کند، اما با سکوت نمی‌تواند."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"The bad news message","tr":"Kötü haber mesajı","fa":"خبر بد را این‌طور بگو"},"steps":[{"en":"Tell them first, before they find out or ask. Then they still trust you.","tr":"Onlar öğrenmeden ya da sormadan önce sen söyle. Böylece sana güvenmeye devam ederler.","fa":"قبل از اینکه خودشان بفهمند یا بپرسند، تو بگو. این‌طوری هنوز به تو اعتماد دارند.","ex":"I'm calling with some bad news about your order."},{"en":"News first, in one sentence. Then what is still on schedule, so they see the whole picture.","tr":"Önce tek cümleyle haber. Sonra neyin hâlâ takvimde olduğu; böylece durumun tamamını görürler.","fa":"اول خبر را در یک جمله بگو. بعد بگو چه چیزی هنوز طبق برنامه است تا همه‌ی وضعیت را ببینند.","ex":"The ship is delayed. The first 10 pallets are safe."},{"en":"Give the reason in one line. Don't blame others: buyers need a plan, not excuses.","tr":"Nedeni tek satırda ver. Başkalarını suçlama: alıcının bahaneye değil, plana ihtiyacı var.","fa":"دلیل را در یک خط بگو. تقصیر را گردن دیگران نینداز: خریدار برنامه می‌خواهد، نه بهانه.","ex":"The port has been closed by a strike since Monday."},{"en":"Give a new date you can keep, and when you will update them.","tr":"Tutabileceğin yeni bir tarih ver ve ne zaman bilgi vereceğini söyle.","fa":"تاریخ جدیدی بده که بتوانی به آن پایبند بمانی و بگو کی دوباره خبر می‌دهی.","ex":"New date: 8 June. I'll update you on Friday."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"News and updates: We have found... / They told us yesterday...","tr":"Haberler ve güncellemeler: We have found... / They told us yesterday...","fa":"خبر و به‌روزرسانی: We have found... و They told us yesterday..."},"steps":[{"en":"News that matters now, with no time given, takes have / has + past participle.","tr":"Şu an önemli olan ve zamanı verilmeyen haber have / has + fiilin üçüncü hâlini alır.","fa":"برای خبری که الان مهم است و زمانش را نمی‌گویی، have یا has و اسم مفعول می‌آوری.","ex":"We have found a problem with the second shipment."},{"en":"A finished time word needs the past simple.","tr":"Bitmiş bir zaman ifadesi past simple ister.","fa":"قید زمان تمام‌شده، مثل yesterday، گذشته‌ی ساده می‌خواهد.","ex":"The port told us on Friday."},{"en":"Yet and already look at now, so they take the present perfect.","tr":"yet ve already şimdiye bakar; bu yüzden present perfect ile kullanılır.","fa":"کلمه‌های yet و already به اکنون نگاه می‌کنند، پس با حال کامل می‌آیند.","ex":"The permit hasn't arrived yet."}],"table":{"headers":{"en":["Use","Form","Example"],"tr":["Kullanım","Biçim","Örnek"],"fa":["کاربرد","ساختار","مثال"]},"rows":[["news now, no time","have / has + past participle","We have found a problem with the second shipment."],["not yet","hasn't / haven't + past participle + yet","The permit hasn't arrived yet."],["finished time","past simple","The port told us on Friday."]]},"tip":{"en":"Turkish uses '-dı' for both ('Bir sorun bulduk', 'Cuma günü söylediler'), and Persian can say «جمعه به ما گفته‌اند» with a perfect form. English is strict: a finished time means past simple.","tr":"Türkçede ikisi için de '-dı' kullanırız: 'Bir sorun bulduk', 'Cuma günü söylediler'. İngilizce bu konuda katıdır: haber şu an önemliyse ve zaman yoksa have found; bitmiş bir zaman varsa told.","fa":"در فارسی می‌شود گفت «جمعه به ما گفته‌اند»، یعنی ماضی نقلی همراه با زمان. انگلیسی سخت‌گیرتر است: اگر زمان تمام‌شده‌ای را بگویی، فقط گذشته‌ی ساده درست است."},"wrong":"We have found the problem yesterday.","right":"We found the problem yesterday."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Call first, then write","tr":"Önce ara, sonra yaz","fa":"اول زنگ بزن، بعد بنویس"},"body":{"en":"For big news, call first, then send it in writing the same day. Don't promise a date just to feel better: a second delay hurts more than a later first date. If you can, offer a real choice, such as part-shipment or air freight.","tr":"Büyük haberlerde önce ara, sonra aynı gün yazılı gönder. Kendini iyi hissetmek için tarih verme: ikinci gecikme, daha geç verilen ilk tarihten çok daha kötüdür. Mümkünse kısmi sevkiyat ya da hava kargosu gibi gerçek bir seçenek sun.","fa":"برای خبر مهم اول زنگ بزن و همان روز کتبی بفرست. برای اینکه خودت آرام شوی تاریخ نده: تأخیر دوم از یک تاریخ دیرتر در بار اول بدتر است. اگر می‌توانی، حق انتخاب واقعی بده؛ مثل ارسال بخشی از سفارش یا حمل هوایی."},"phrases":[{"phrase":"I'm calling with some bad news.","meaning":{"en":"Says it at once.","tr":"Hemen söyler.","fa":"خبر را فوری می‌گوید."}},{"phrase":"We have just found out that ...","meaning":{"en":"Gives fresh news.","tr":"Yeni haberi verir.","fa":"خبر تازه را می‌دهد."}},{"phrase":"I'll update you on ...","meaning":{"en":"Sets your next message.","tr":"Bir sonraki mesajını belirler.","fa":"زمان پیام بعدی‌ات را مشخص می‌کند."}},{"phrase":"delay","meaning":{"en":"Time when something is later than planned.","tr":"gecikme.","fa":"تأخیر"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Say it clearly","tr":"Açıkça söyle","fa":"روشن بگو"},"item":"Unfortunately, due to unforeseen circumstances beyond our control, there may possibly be some issues with timing. Your facts: 20 pallets, due 1 June, now 8 June; the ship was delayed at the port; you booked the next one; next update on Friday.","answer":"Your 20 pallets will arrive on 8 June, not 1 June. The ship has been delayed at the port. We have booked the next one, and I'll update you on Friday.","walk":[{"en":"Give the news in the first line, with the two dates.","tr":"Haberi ilk satırda, iki tarihle birlikte ver.","fa":"خبر را در خط اول با هر دو تاریخ بده."},{"en":"Replace the vague words with one true reason.","tr":"Belirsiz sözlerin yerine tek bir gerçek neden koy.","fa":"به‌جای حرف‌های مبهم یک دلیل واقعی بگذار."},{"en":"End with what you are doing and your next update.","tr":"Ne yaptığın ve bir sonraki bilgilendirmenle bitir.","fa":"در آخر بگو چه کار می‌کنی و کی دوباره خبر می‌دهی."}]},"quick":{"prompt":"Tell a customer about a delay ___.","options":["as soon as you know","on the old delivery date","only if they ask"],"correct":0,"why":{"en":"as soon as you know: an early warning gives them time to plan. Late news costs them more.","tr":"as soon as you know: erken uyarı planlama zamanı verir. Geç haber onlara daha pahalıya patlar.","fa":"جواب as soon as you know است، چون هشدار زود به آن‌ها وقت برنامه‌ریزی می‌دهد و خبر دیر برایشان گران‌تر تمام می‌شود."}},"remember":{"en":"News, reason, new date, action, next update. You can now tell a customer about a delay early and clearly, with a plan.","tr":"Haber, neden, yeni tarih, eylem, sonraki bilgilendirme. Artık bir gecikmeyi müşteriye erken ve net biçimde, planıyla birlikte söyleyebilirsin.","fa":"خبر را بگو، بعد دلیل، تاریخ جدید، کاری که می‌کنی و زمان خبر بعدی را. حالا می‌توانی تأخیر را زود و روشن و همراه با برنامه به مشتری بگویی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Showing effort: We have been calling them since Monday","tr":"Çabayı göstermek: We have been calling them since Monday","fa":"نشان دادن تلاش: We have been calling them since Monday"},"steps":[{"en":"Started in the past, still going on: have / has been + -ing.","tr":"Geçmişte başladı, hâlâ sürüyor: have / has been + -ing.","fa":"برای کاری که در گذشته شروع شده و ادامه دارد، have been یا has been و فعل با ing می‌آوری.","ex":"We have been calling them since Monday."},{"en":"since + a start point; for + a length of time.","tr":"since + başlangıç noktası; for + süre.","fa":"بعد از since نقطه‌ی شروع می‌آید و بعد از for مدت زمان.","ex":"since Monday / for two weeks"},{"en":"Not am / is / are + -ing with since or for.","tr":"since ya da for ile am / is / are + -ing olmaz.","fa":"با since یا for از am، is یا are و فعل با ing استفاده نکن.","ex":"not: We are calling them since Monday"}],"table":{"headers":{"en":["Form","Example"],"tr":["Biçim","Örnek"],"fa":["ساختار","مثال"]},"rows":[["have / has been + -ing + since","We have been calling them since Monday."],["have / has been + -ing + for","We have been waiting for two weeks."],["not: am / are + -ing + since","not: We are calling them since Monday."]]},"body":{"en":"B2: show your effort once with have been + -ing and since or for.","tr":"B2: çabanı bir kez have been + -ing ve since ya da for ile göster.","fa":"مسیر B2: یک بار تلاشت را با have been و فعل با ing، همراه با since یا for، نشان بده."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
